export const ABILITIES=[{key:'strength',short:'СИЛ',full:'Сила',icon:'✦'},{key:'dexterity',short:'ЛОВ',full:'Ловкость',icon:'➶'},{key:'constitution',short:'ТЕЛ',full:'Телосложение',icon:'♥'},{key:'intelligence',short:'ИНТ',full:'Интеллект',icon:'✣'},{key:'wisdom',short:'МДР',full:'Мудрость',icon:'◉'},{key:'charisma',short:'ХАР',full:'Харизма',icon:'✧'}];
export const modifier=value=>Math.floor((Number(value)-10)/2);export const signed=value=>value>=0?`+${value}`:`−${Math.abs(value)}`;export const clampScore=value=>Math.max(1,Math.min(30,Math.trunc(Number(value))||10));
export function createRecord(type,fields,device='local'){const now=new Date().toISOString();return{id:crypto.randomUUID(),type,created_at:now,updated_at:now,version:1,device_id:device,deleted_at:null,...fields}}
export const equal=(a,b)=>JSON.stringify(a??null)===JSON.stringify(b??null);
export function mergeRecords(local,remote,base=[]){const l=new Map(local.map(e=>[e.id,e])),r=new Map(remote.map(e=>[e.id,e])),b=new Map(base.map(e=>[e.id,e])),result=[];for(const id of new Set([...l.keys(),...r.keys()])){const left=l.get(id),right=r.get(id),before=b.get(id);if(!left||!right){result.push(structuredClone(left||right));continue}if(equal(left,right)){result.push(structuredClone(left));continue}const out={...right},conflicts=new Map([...(right.conflicts||[]),...(left.conflicts||[])].map(c=>[c.id,c]));for(const key of new Set([...Object.keys(left),...Object.keys(right)])){if(['conflicts','version','updated_at','device_id'].includes(key))continue;const lc=!equal(left[key],before?.[key]),rc=!equal(right[key],before?.[key]);if(lc&&!rc)out[key]=left[key];else if(lc&&rc&&!equal(left[key],right[key])){const winner=left.updated_at>right.updated_at?left:right;out[key]=winner[key];if(['content','description','name','title','party','goal','deleted_at','image_id'].includes(key)){const cid=`${id}:${key}:${left.updated_at}:${right.updated_at}`;conflicts.set(cid,{id:cid,field:key,local:left[key]??null,remote:right[key]??null,local_device:left.device_id,remote_device:right.device_id,local_date:left.updated_at,remote_date:right.updated_at})}}}out.conflicts=[...conflicts.values()];out.version=Math.max(left.version||1,right.version||1);out.updated_at=left.updated_at>right.updated_at?left.updated_at:right.updated_at;out.device_id=left.updated_at>right.updated_at?left.device_id:right.device_id;result.push(out)}return result}
export function migrateLegacy(data){const value=data;if(value?.format==='seeker-notebook-3'&&Array.isArray(value.records))return value.records;if(!Array.isArray(value?.campaigns))return[];const records=[];for(const campaign of value.campaigns){const stamp=new Date(campaign.updatedAt||campaign.createdAt||value.clientUpdatedAt||Date.now()).toISOString(),id=campaign.id||crypto.randomUUID();records.push(createRecord('party',{id,title:campaign.name||'Без названия',description:campaign.subtitle||'',party:campaign.party||'',goal:campaign.goal||'',players_count:0,status:'В процессе',start_date:'',created_at:stamp,updated_at:stamp,device_id:value.deviceId||'Прежняя версия'}));for(const[kind,label,content]of[['history','История',campaign.journal||''],['notes','Заметки',campaign.quickNotes||'']])records.push(createRecord('section',{id:`${id}:${kind}`,parent_id:id,kind,title:label,content,created_at:stamp,updated_at:stamp,device_id:value.deviceId||'Прежняя версия'}));for(const session of campaign.sessions||[]){const sid=session.id||crypto.randomUUID();records.push(createRecord('session',{id:sid,parent_id:id,title:session.title||'Игровой день',date:session.date||'',location:session.location||'',description:session.teaser||'',content:session.notes||'',image_id:`legacy-${sid}`,created_at:stamp,updated_at:stamp,device_id:value.deviceId||'Прежняя версия'}))}}return records}
export const escapeHtml=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
export function sanitizeHtml(html){const template=document.createElement('template');template.innerHTML=html||'';const allowed=new Set(['P','BR','B','STRONG','UL','OL','LI']),nodes=[...template.content.querySelectorAll('*')];for(const node of nodes){if(!allowed.has(node.tagName)){node.replaceWith(...node.childNodes);continue}for(const attribute of[...node.attributes])node.removeAttribute(attribute.name)}return template.innerHTML}
